-- public.reschedule_visit(p_visit_id uuid, p_visit_date date, p_time_start time without time zone, p_time_end time without time zone, p_reason text, p_idempotency_key uuid, p_overlap_shown boolean, p_member_overlap_shown boolean)
CREATE OR REPLACE FUNCTION public.reschedule_visit(p_visit_id uuid, p_visit_date date, p_time_start time without time zone, p_time_end time without time zone, p_reason text, p_idempotency_key uuid, p_overlap_shown boolean DEFAULT NULL::boolean, p_member_overlap_shown boolean DEFAULT NULL::boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  uid    uuid := (select auth.uid());
  v      public.care_visits%rowtype;
  before jsonb;
  why    text := private.check_text(p_reason, 3, 300, 'reason');
  ab_id  uuid;
  ab_rng tstzrange;
  n_rel  integer := 0;
  absent boolean := false;
  mo     boolean;
  tk     uuid;
  new_iv tstzrange;
begin
  if uid is null then
    return jsonb_build_object('result', 'rejected', 'reason', 'not_team_member');
  end if;
  perform private.check_visit_slot(p_visit_date, p_time_start, p_time_end);
  if private.begin_command('reschedule_visit', p_idempotency_key) then
    perform private.end_command('duplicate');
    return jsonb_build_object('result', 'duplicate');
  end if;

  select * into v from public.care_visits where id = p_visit_id for update;
  -- BK-E1B-M (CGR-249): a visit written from a take is never moved or re-dated by a person command.
  if found and v.order_take_id is not null
     and private.is_org_member(v.organization_id) and private.is_team_member(v.team_id) then
    perform private.write_visit_refusal(v, 'reschedule_visit', 'take_visit');  -- BK-E1B-R (CGR-252): one row
    perform private.end_command('take_visit');
    return jsonb_build_object('result', 'take_visit');
  end if;
  if not found or v.status <> 'planned'
     or not private.is_org_member(v.organization_id) or not private.is_team_member(v.team_id) then
    perform private.end_command('rejected');
    return jsonb_build_object('result', 'rejected', 'reason', 'not_team_member');
  end if;
  if coalesce(v.planned_minutes_a, 0) + coalesce(v.planned_minutes_b, 0) + coalesce(v.planned_minutes_c, 0)
     > extract(epoch from (p_time_end - p_time_start)) / 60 then
    perform private.end_command('rejected');
    return jsonb_build_object('result', 'rejected', 'reason', 'minutes_exceed_window');
  end if;
  -- HD-3s-F2-F1 (PO decision CGR-289 (c), ADR-230): never into the window of a live take of its responsible or covering
  -- person (pause included); one refusal row as every visit refusal (CGR-252), nothing moves, the take stays live. The
  -- person locks first, in the fixed order of recheck_takes_trigger (CGR-255).
  if v.responsible_user_id is not null or v.covered_by is not null then
    perform pg_advisory_xact_lock(hashtextextended('order_take_member:' || p.u::text, 0))
    from (select distinct u from unnest(array[v.responsible_user_id, v.covered_by]) u where u is not null) p order by p.u;
    new_iv := private.visit_interval(jsonb_populate_record(v, jsonb_build_object(
                'visit_date', p_visit_date, 'time_start', p_time_start, 'time_end', p_time_end)));
    tk := coalesce(private.member_take_window(v.responsible_user_id, new_iv, null),
                   private.member_take_window(v.covered_by, new_iv, null));
    if tk is not null then
      perform private.write_visit_refusal(v, 'reschedule_visit', 'member_take_window');
      perform private.end_command('rejected');
      return jsonb_build_object('result', 'rejected', 'reason', 'member_take_window',
                                'take', private.member_take_window_facts(tk, v.team_id));
    end if;
  end if;

  -- ABS1-C5: the move, its log and the ABS1-C4 release run in one subtransaction, undone together when refused.
  begin
  before := private.visit_slot_json(v);
  -- AN2 / CGR-35: the CGR-32 condition, read before the move; stored, never taken from the caller.
  absent := v.status = 'planned'
            and v.visit_date < (private.at_zurich(private.now()))::date
            and private.visit_responsible_absent(v.id);
  update public.care_visits set visit_date = p_visit_date, time_start = p_time_start, time_end = p_time_end
  where id = v.id returning * into v;

  -- VIS2-4 (ADR-121): what the form showed, on this command's audit row only.
  perform set_config('navora.overlap_shown', coalesce(p_overlap_shown::text, ''), true);
  -- PLAN3-16 (ADR-161): what the form showed about the member, on this command's audit row only.
  perform set_config('navora.member_overlap_shown', coalesce(p_member_overlap_shown::text, ''), true);
  insert into public.visit_plan_changes (organization_id, visit_id, case_id, team_id, change, before, after, reason, actor_id,
                                         responsible_absent)
  values (v.organization_id, v.id, v.case_id, v.team_id, 'moved', before, private.visit_slot_json(v), why, uid, absent);
  perform set_config('navora.overlap_shown', '', true);
  perform set_config('navora.member_overlap_shown', '', true);

  -- ABS1-C4: moved into the absence of its responsible member -> released through the one release rule (not refused).
  if v.responsible_user_id is not null
     and private.member_absent_during(v.team_id, v.responsible_user_id,
                                      lower(private.visit_interval(v)), upper(private.visit_interval(v))) then
    select case when a.team_id = v.team_id then a.id end,
           tstzrange(a.starts_at, a.ends_at, '[)') * private.visit_interval(v)
      into ab_id, ab_rng
      from public.member_absences a
      where a.organization_id = v.organization_id and a.user_id = v.responsible_user_id and a.withdrawn_at is null
        and tstzrange(a.starts_at, a.ends_at, '[)') && private.visit_interval(v)
      order by (a.team_id = v.team_id) desc, a.starts_at
      limit 1;
    if ab_id is not null then
      insert into public.absence_releases (absence_id, visit_id)
      select ab_id, r from private.release_visits_between(v.team_id, v.responsible_user_id, lower(ab_rng), upper(ab_rng),
                                                          'Abwesenheit', uid, false) r
      on conflict do nothing;
    else
      perform private.release_visits_between(v.team_id, v.responsible_user_id, lower(ab_rng), upper(ab_rng),
                                             'Abwesenheit', uid, false);
    end if;
    select * into v from public.care_visits where id = v.id;
    n_rel := case when v.responsible_user_id is null then 1 else 0 end;
  end if;

  -- ABS1-C5: never leave the visit with a member absent at its interval (the release rule skips past visits).
  if v.responsible_user_id is not null
     and private.member_absent_during(v.team_id, v.responsible_user_id,
                                      lower(private.visit_interval(v)), upper(private.visit_interval(v))) then
    raise exception using errcode = 'NVC05', message = 'abs1-c5: responsible member absent after the move';
  end if;
  exception when sqlstate 'NVC05' then
    perform private.end_command('rejected');
    return jsonb_build_object('result', 'rejected', 'reason', 'responsible_absent');
  end;

  -- PLAN3-16: the member-overlap fact after the move (null when the visit has, or was released to, no member).
  if v.responsible_user_id is not null then
    mo := private.member_visit_overlap(v.id, v.responsible_user_id);
  end if;
  perform private.end_command('ok');
  -- VIS2-5 (ADR-121): the server's own check at the save, whatever the form showed.
  return jsonb_build_object('result', 'ok', 'visit_id', v.id, 'released', n_rel = 1,
    'overlap', private.client_overlap_fact(v.case_id, v.visit_date, v.time_start, v.time_end, v.id),
    'member_overlap', mo,
    'flags', to_jsonb(private.visit_flags(v.case_id, v.visit_date, v.planned_minutes_b, v.responsible_user_id, v.status, v.time_start)));
end;
$function$;

revoke all on function public.reschedule_visit(p_visit_id uuid, p_visit_date date, p_time_start time without time zone, p_time_end time without time zone, p_reason text, p_idempotency_key uuid, p_overlap_shown boolean, p_member_overlap_shown boolean) from public, anon, authenticated, service_role;
grant execute on function public.reschedule_visit(p_visit_id uuid, p_visit_date date, p_time_start time without time zone, p_time_end time without time zone, p_reason text, p_idempotency_key uuid, p_overlap_shown boolean, p_member_overlap_shown boolean) to authenticated;
grant execute on function public.reschedule_visit(p_visit_id uuid, p_visit_date date, p_time_start time without time zone, p_time_end time without time zone, p_reason text, p_idempotency_key uuid, p_overlap_shown boolean, p_member_overlap_shown boolean) to service_role;
comment on function public.reschedule_visit(p_visit_id uuid, p_visit_date date, p_time_start time without time zone, p_time_end time without time zone, p_reason text, p_idempotency_key uuid, p_overlap_shown boolean, p_member_overlap_shown boolean) is 'J3: moves a planned visit with a reason. ABS1-C4: a move into the absence of its responsible member is not refused; the visit is released (fixed text Abwesenheit) and returns {result, visit_id, released: true, flags}. ABS1-C5: when the visit would still name a member absent at its interval (a date the release rule does not cover, i.e. before today), the move is refused with responsible_absent and nothing is written. AN2 / CGR-35: a past planned visit whose responsible member is recorded absent at its interval is moved with responsible_absent = true on its moved row (server side). VIS2 (ADR-121): p_overlap_shown (what the form showed) is recorded as overlap_shown on the moved audit row; an ok result carries overlap (the server''s check). Never refused for an overlap. PLAN3-16 (ADR-161): p_member_overlap_shown is recorded as member_overlap_shown on the moved audit row; an ok result carries member_overlap (yes/no, any team). Never refused for it. BK-e1b / CGR-249: a visit written from a take (order_take_id) is refused with take_visit; the way out is the release (CGR-242). BK-e1b / CGR-252: a take_visit refusal writes one audit row (outcome take_visit, no key). HD-3s-F2-F1 (CGR-289 (c), ADR-230): a move into the window of a live take of its responsible or covering person (pause included) is refused with reason member_take_window and the take named (work date, blocks, the home only within its own team); one refusal row, nothing moves.';
